'use client';

import * as React from 'react';
import { cn } from '../lib/utils';
import { 
  LayoutDashboard, Users, Kanban, ShoppingCart, Package, 
  Ticket, Truck, Settings, Bot, Megaphone, Sparkles,
  ChevronLeft, ChevronRight, Menu
} from 'lucide-react';
import { Button } from './Button';

const navigation = [
  { key: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, href: '/dashboard' },
  { key: 'leads', label: 'Leads', icon: Users, href: '/leads' },
  { key: 'pipeline', label: 'Pipeline', icon: Kanban, href: '/pipeline' },
  { key: 'deals', label: 'Deals', icon: ShoppingCart, href: '/deals' },
  { key: 'orders', label: 'Orders', icon: Package, href: '/orders' },
  { key: 'inventory', label: 'Inventory', icon: Package, href: '/inventory' },
  { key: 'tickets', label: 'Tickets', icon: Ticket, href: '/tickets' },
  { key: 'procurement', label: 'Procurement', icon: Truck, href: '/procurement' },
];

const aiNavigation = [
  { key: 'command-center', label: 'Command Center', icon: Bot, href: '/aion/command-center' },
  { key: 'campaigns', label: 'Campaigns', icon: Megaphone, href: '/aion/campaigns' },
  { key: 'ai-plus', label: 'AI+ Workspace', icon: Sparkles, href: '/aion/ai-plus' },
];

const adminNavigation = [
  { key: 'settings', label: 'Settings', icon: Settings, href: '/settings' },
];

export interface SidebarProps {
  collapsed?: boolean;
  onToggle?: () => void;
  currentPath?: string;
}

export function Sidebar({ collapsed = false, onToggle, currentPath = '' }: SidebarProps) {
  const [mobileOpen, setMobileOpen] = React.useState(false);

  const isActive = (href: string) => currentPath === href || currentPath.startsWith(href + '/');

  const navGroups = [
    { label: 'Sales', items: navigation },
    { label: 'AI', items: aiNavigation },
    { label: 'Admin', items: adminNavigation },
  ];

  if (typeof window === 'undefined') return null;

  return (
    <>
      <Button
        variant="ghost"
        size="icon"
        className="lg:hidden fixed top-4 left-4 z-[300]"
        onClick={() => setMobileOpen(true)}
        aria-label="Open navigation"
      >
        <Menu className="h-5 w-5" />
      </Button>

      {mobileOpen && (
        <div
          className="fixed inset-0 z-[299] bg-overlay lg:hidden"
          onClick={() => setMobileOpen(false)}
          aria-hidden="true"
        />
      )}

      <aside
        className={cn(
          'fixed left-0 top-0 h-full z-[200] bg-surface border-r border-border transition-all duration-normal flex flex-col',
          collapsed ? 'w-[72px]' : 'w-[280px]',
          mobileOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        )}
        aria-label="Main navigation"
      >
        <div className="flex items-center justify-between h-[64px] px-4 border-b border-border">
          {!collapsed && (
            <a href="/dashboard" className="flex items-center gap-2" aria-label="Step-in-CRM Home">
              <div className="h-8 w-8 rounded-lg bg-accent flex items-center justify-center">
                <span className="text-on-accent font-bold text-lg">S</span>
              </div>
              <span className="font-semibold text-text">Step-in-CRM</span>
            </a>
          )}
          <Button
            variant="ghost"
            size="icon"
            onClick={onToggle}
            aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            className={cn('flex items-center justify-center', collapsed && 'mx-auto')}
          >
            {collapsed ? <ChevronRight className="h-5 w-5" /> : <ChevronLeft className="h-5 w-5" />}
          </Button>
        </div>

        <nav className="flex-1 overflow-y-auto py-4 px-2" aria-label="Navigation">
          {navGroups.map((group, groupIndex) => (
            <div key={group.label} className="mb-6">
              {!collapsed && (
                <h3 className="px-3 text-xs font-semibold text-text-muted uppercase tracking-wider mb-2">
                  {group.label}
                </h3>
              )}
              <ul className="space-y-1" role="list">
                {group.items.map((item) => (
                  <li key={item.key}>
                    <a
                      href={item.href}
                      className={cn(
                        'flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors duration-fast',
                        'hover:bg-surface-elevated',
                        isActive(item.href) 
                          ? 'bg-accent-light text-accent border-l-2 border-accent' 
                          : 'text-text-muted hover:text-text',
                        collapsed && 'justify-center'
                      )}
                      aria-current={isActive(item.href) ? 'page' : undefined}
                      title={collapsed ? item.label : undefined}
                    >
                      <item.icon className="h-5 w-5 shrink-0" aria-hidden="true" />
                      {!collapsed && <span className="font-medium text-sm">{item.label}</span>}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-border">
          {!collapsed && (
            <div className="text-xs text-text-muted text-center">
              Step-in-CRM v0.1.0
            </div>
          )}
        </div>
      </aside>
    </>
  );
}